    elif lawyer.gender == 'female':
        gender_penalty = 0
    else:
        gender_penalty = -0.5

    if lawyer.age == 'young':
        age_bonus = 1
    elif lawyer.age == 'middle':
        age_bonus = 0
    elif lawyer.age == 'elder':
        age_bonus = -1
    else:
        age_bonus = 0

    score = (
        (lawyer.analytical_skills if lawyer.analytical_skills <= 10 else 10) +
        (lawyer.ethical_judgment if lawyer.ethical_judgment <= 10 else 10) +
        (10 - (lawyer.research_skills if lawyer.research_skills <= 5 else 5)) +
        (lawyer.communication_skills if lawyer.communication_skills <= 10 else 10) +
        gender_penalty + age_bonus
    )

    return score

