def factorial(n):
    """Calculate the factorial of a number."""
    if n < 0:
        return "Error! Factorial of a negative number doesn't exist."
    elif n == 0:
        return 1
    else:
        factorial = 1
        for i in range(1, n + 1):
            factorial *= i
        return factorial

